        function formatAllergyCopy(item) {
            if (!item) return "";

            let parts = [];

            parts.push(`Allergy : ${item.AllergyName}`);

            if (item.ReactionName)
                parts.push(`Reaction : ${item.ReactionName}`);

            if (item.SeverityName)
                parts.push(`Severity : ${item.SeverityName}`);

            if (item.StatusName)
                parts.push(`Status : ${item.StatusName}`);

            if (item.Duration) {
                let unitMap = { D: "Days", W: "Weeks", M: "Months", Y: "Years", SB: "Since Birth" };
                let unit = unitMap[item.DurationType] || "";
                parts.push(
                    item.DurationType === "SB"
                        ? `Duration : Since Birth`
                        : `Duration : ${item.Duration} ${unit}`
                );
            }

            if (item.DurationDate)
                parts.push(`Onset : ${$filter('date')(item.DurationDate, "MM-dd-yyyy")}`);

            if (item.Remarks)
                parts.push(`Notes : ${item.Remarks}`);

            return parts.join(", ");
        }
        function formatOcularHistoryCopy(item) {
            if (!item) return "";

            let details = `Occular History : ${item.HistoryName}`;

            function getUnit(type) {
                switch (type) {
                    case 'D': return 'Days';
                    case 'W': return 'Weeks';
                    case 'M': return 'Months';
                    case 'Y': return 'Years';
                    case 'SB': return 'Since Birth';
                    default: return '';
                }
            }

            // OD
            if (item.RDuration) {
                details += item.RDurationType === 'SB'
                    ? `, OD Duration: Since Birth`
                    : `, OD Duration: ${item.RDuration} ${getUnit(item.RDurationType)}`;
            }

            // OS
            if (item.LDuration) {
                details += item.LDurationType === 'SB'
                    ? `, OS Duration: Since Birth`
                    : `, OS Duration: ${item.LDuration} ${getUnit(item.LDurationType)}`;
            }

            if (item.RDurationDate)
                details += `, OD Duration Date: ${item.RDurationDate}`;

            if (item.LDurationDate)
                details += `, OS Duration Date: ${item.LDurationDate}`;

            if (item.RSeverityName)
                details += `, OD Severity: ${item.RSeverityName}`;

            if (item.LSeverityName)
                details += `, OS Severity: ${item.LSeverityName}`;

            if (item.RStatusName)
                details += `, OD Status: ${item.RStatusName}`;

            if (item.LStatusName)
                details += `, OS Status: ${item.LStatusName}`;

            if (item.SNOMEDCODE)
                details += `, SNOMED: ${item.SNOMEDCODE}`;

            if (item.ICD10CODE)
                details += `, ICD-10: ${item.ICD10CODE}`;

            if (item.Remarks)
                details += `, Notes: ${item.Remarks}`;

            return details;
        }
         
        function formatOccularSurgicalHistoryCopy(item) {
            if (!item) return "";
            let details = `Ocular Surgical History :${item.HistoryName}`;
            if (item.RDuration) {
                let unit = '';
                switch (item.RDurationType) {
                    case 'D':
                        unit = 'Days';
                        break;
                    case 'W':
                        unit = 'Weeks';
                        break;
                    case 'M':
                        unit = 'Months';
                        break;
                    case 'Y':
                        unit = 'Years';
                        break;
                    case 'SB':
                        unit = 'Since Birth';
                        break;
                }

                if (item.RDurationType === 'SB') {
                    details += `, OD Duration: Since Birth`;
                } else {
                    details += `, OD Duration: ${item.RDuration} ${unit}`;
                }
            }
            if (item.LDuration) {
                let unit = '';
                switch (item.LDurationType) {
                    case 'D':
                        unit = 'Days';
                        break;
                    case 'W':
                        unit = 'Weeks';
                        break;
                    case 'M':
                        unit = 'Months';
                        break;
                    case 'Y':
                        unit = 'Years';
                        break;
                    case 'SB':
                        unit = 'Since Birth';
                        break;
                }

                if (item.LDurationType === 'SB') {
                    details += `, OS Duration: Since Birth`;
                } else {
                    details += `, OS Duration: ${item.LDuration} ${unit}`;
                }
            }
            if (item.RDurationDate) {
                details += `, OD DurationDate: ${item.RDurationDate}`;
            }
            if (item.LDurationDate) {
                details += `, OS DurationDate: ${item.LDurationDate}`;
            }
            if (item.RPerformedName && item.RPerformedName.trim() !== '') {
                details += `, OD Performed by: ${item.RPerformedName}`;
            }
            if (item.LPerformedName && item.LPerformedName.trim() !== '') {
                details += `, OS Performed by: ${item.LPerformedName}`;
            }
            if (item.RCoManagedName) {
                details += `, OD Co-Managed by: ${item.RCoManagedName}`;
            }
            if (item.LCoManagedName) {
                details += `, OS Co-Managed by: ${item.LCoManagedName}`;
            }
            if (item?.CPTCode) {
                details += `, CPT Code: ${item.CPTCode}`;
            }

            if (item.Remarks) {
                details += `, Notes: ${item.Remarks}`;
            }
            return details;
        }

        function formatCurrentEyeMedicationsCopy(item) {
            if (!item) return "";
            let getRefillName = id => ($filter("filter")($scope.refillsArray, { MedicineDosaageFieldId: id || 0 }, true)[0] || {}).Description || "";
            let getQuantityUnitName = id => ($filter("filter")($scope.quantityUnitArray, { MedicineDosaageFieldId: id || 0 }, true)[0] || {}).Description || "";

            let medicineInfo = item.MedicineName;
            item.Sig = item.Sig || '';
            item.StartDate = item.StartDate ? $filter('date')(item.StartDate, 'MM-dd-yyyy') : null;
            item.StopDate = item.StartDate ? $filter('date')(item.StopDate, 'MM-dd-yyyy') : null;


            if (item.Sig !== '') {
                medicineInfo += ' Sig:' + item.Sig;
            }
            if (item.StartDate) {
                medicineInfo += ' StartDate:' + item.StartDate;
            }
            if (item.RefillId) medicineInfo += ' Refill:' + getRefillName(item.RefillId);
            if (item.Quantity) medicineInfo += ' Quantity:' + item.Quantity;
            if (item.QuantityUnitId) medicineInfo += ' Quantity Unit:' + getQuantityUnitName(item.QuantityUnitId);
            if (item.MedicineId != 1) {
                if (item.SubstitutionPermitted !== undefined) {
                    let subNew = item.SubstitutionPermitted === "y" ? "Yes" : "No";
                    medicineInfo += ' Substitution:' + subNew;
                }
            }
            if (item.StopDate) medicineInfo += ' StopDate:' + item.StopDate;
            if (item.StopReasonId) medicineInfo += ' Reason:' + item.StopReason;
            if (item.PatientInstructions) medicineInfo += ' Instructions:' + item.PatientInstructions;


            return medicineInfo;
        }
