        function formatLifestyleCopy(lifestyleArr, remarks) {

            if (!lifestyleArr || lifestyleArr.length === 0) return "";

            const formatDuration = (value, type) => {
                if (!value) return '';
                const labels = { Y: 'Year(s)', W: 'Week(s)', M: 'Month(s)', D: 'Day(s)', H: 'Hour(s)' };
                return `${value} ${labels[type] || ''}`;
            };

            let sections = [];

            // -------- Smoking (HistoryId = 1) --------
            let smoking = lifestyleArr.filter(x => x.DeleteInd === 'N' && x.HistoryId === 1);
            if (smoking.length) {
                let lines = smoking.map(item => {
                    let parts = [];
                    if (item.HistoryName) parts.push(`History Name : ${item.HistoryName}`);
                    if (item.SmokingType) parts.push(`Smoking Type : ${item.SmokingType}`);
                    if (item.SmokingFromDate)
                        parts.push(`Smoking From Date : ${item.SmokingFromDate}`);
                    else if (item.SmokingDuration)
                        parts.push(`Smoking Duration : ${formatDuration(item.SmokingDuration, item.SmokingDurationType)}`);
                    if (item.SmokingStatusName) parts.push(`Status : ${item.SmokingStatusName}`);
                    if (item.SmokingQuantityName) parts.push(`Quantity : ${item.SmokingQuantityName}`);
                    return parts.join(" , ");
                });
                sections.push(`Smoking\n${lines.join("\n")}`);
            }

            // -------- Alcohol (HistoryId = 2) --------
            let alcohol = lifestyleArr.filter(x => x.DeleteInd === 'N' && x.HistoryId === 2);
            if (alcohol.length) {
                let lines = alcohol.map(item => {
                    let parts = [];
                    if (item.HistoryName) parts.push(`History Name : ${item.HistoryName}`);
                    if (item.AlcoholType) parts.push(`Alcohol Type : ${item.AlcoholType}`);
                    if (item.AlcoholDurationDate)
                        parts.push(`Alcohol Duration Date : ${item.AlcoholDurationDate}`);
                    else if (item.AlcoholDuration)
                        parts.push(`Alcohol Duration : ${formatDuration(item.AlcoholDuration, item.AlcoholDurationType)}`);
                    if (item.AlcoholStatusName) parts.push(`Status : ${item.AlcoholStatusName}`);
                    if (item.AlcoholQuantityName) parts.push(`Quantity : ${item.AlcoholQuantityName}`);
                    return parts.join(" , ");
                });
                sections.push(`Alcohol\n${lines.join("\n")}`);
            }

            // -------- Drug (HistoryId = 3) --------
            let drug = lifestyleArr.filter(x => x.DeleteInd === 'N' && x.HistoryId === 3);
            if (drug.length) {
                let lines = drug.map(item => {
                    let parts = [];
                    if (item.HistoryName) parts.push(`History Name : ${item.HistoryName}`);
                    if (item.DrugType) parts.push(`Drug Type : ${item.DrugType}`);
                    if (item.DrugDurationDate)
                        parts.push(`Drug Duration Date : ${item.DrugDurationDate}`);
                    else if (item.DrugDuration)
                        parts.push(`Drug Duration : ${formatDuration(item.DrugDuration, item.DrugDurationType)}`);
                    if (item.DrugArray?.length)
                        parts.push(`Drugs : ${item.DrugArray.map(d => d.HabitsDescription).join(', ')}`);
                    if (item.DrugQuantityName) parts.push(`How Much : ${item.DrugQuantityName}`);
                    if (item.DrugWhenQuit) parts.push(`When Stopped : ${item.DrugWhenQuit}`);
                    return parts.join(" , ");
                });
                sections.push(`Drug\n${lines.join("\n")}`);
            }

            // -------- Psychis (HistoryId = 4) --------
            let psychis = lifestyleArr.filter(x => x.DeleteInd === 'N' && x.HistoryId === 4);
            if (psychis.length) {
                let lines = psychis.map(item => {
                    let parts = [];
                    if (item.HistoryName) parts.push(`History Name : ${item.HistoryName}`);
                    if (item.PsychisType) parts.push(`Psychis Type : ${item.PsychisType}`);
                    return parts.join(" , ");
                });
                sections.push(`Psychis\n${lines.join("\n")}`);
            }

            // -------- Remarks --------
            if (remarks) {
                sections.push(`Lifestyle History Notes : ${remarks}`);
            }

            return sections.join("\n\n");
        }
