        $scope.CopyFamilyHistory = function (sourceArray, remarks, sourceItem) {
            let duplicateFound = false;
            let copiedLogs = [];
            angular.forEach(sourceArray, function (fa) {       
                const exists = $scope.obj.FamilyHistory
                    .some(e => e.HistoryId === fa.HistoryId);

                if (exists) {
                    duplicateFound = true;
                    return;
                } else {
                    if ($scope.obj.FamilyHistory.length !== 0) {
                        var List = $filter("filter")($scope.obj.FamilyHistory, { "HistoryId": 1 }, true);
                        if (List.length > 0) {
                            if (List[0].PatientDetailId === 0) {
                                var indexToRemove = $scope.obj.FamilyHistory.indexOf(List[0]);
                                if (indexToRemove !== -1) {
                                    $scope.obj.FamilyHistory.splice(indexToRemove, 1);
                                }
                            } else {
                                List[0].DeleteInd = 'Y';
                            }
                        }

                        angular.forEach($scope.obj.FamilyHistory, function (item, index) {


                            item.IsEdit = false;

                        });
                    }
                }

                let subArray = (fa.FamilyHistorySubArray || []).map(sub => ({
                    SubFamilyDetailId:  0,
                    Remarks: sub.Remarks || "",
                    RelationAge: sub.RelationAge || "",
                    Status: sub.Status || "",
                    RelationShipId: sub.RelationShipId || "",
                    RelationShipName: sub.RelationShipName || "",
                    SubRelation: sub.SubRelation || "",
                    DeleteInd: "N",
                    ShowNote: !!sub.Remarks
                }));

                if (subArray.length === 0) {
                    subArray = [{
                        SubFamilyDetailId: 0,
                        Remarks: "",
                        RelationAge: "",
                        Status: "",
                        RelationShipId: "",
                        RelationShipName: "",
                        SubRelation: "",
                        DeleteInd: "N",
                        ShowNote: false
                    }];
                }              
                const newHistory = {
                    PatientDetailId: null,
                    HistoryId: fa.HistoryId,
                    HistoryName: fa.HistoryName,
                    IsEdit: fa.IsEdit || false,
                    showFamilyHistory: false,
                    ActiveInd: true,
                    DeleteInd: 'N',
                    IsFrequent: fa.IsFrequent || "",
                    FamilyHistorySubArray: subArray
                };

                if (newHistory.HistoryId === 1 && $scope.obj.FamilyHistory.length > 0) {
                    return false;
                }

                $scope.obj.isNKFHSelected = false;
                if (newHistory.HistoryId === 1) {
                    $scope.obj.isNKFHSelected = true;
                }           
                $scope.obj.FamilyHistory.push(newHistory);
               // copiedLogs.push(formatFamilyHistoryCopy(newHistory));
                $scope.obj.FamilyHistoryRemarks = remarks || "";
                sourceItem.IsFamilycopied = true;
            });

            //if ($scope.obj.FamilyHistoryRemarks) {
            //    copiedLogs += `\Family History Notes : ${$scope.obj.FamilyHistoryRemarks}`;
            //}

            //if (copiedLogs.length > 0) {
            //    sourceItem.AppointmentDate = $filter('date')(sourceItem.AppointmentDate, "MM-dd-yyyy");
            //    let LogItem = {
            //        LogId: 0,
            //        ModuleId: 1,
            //        ModuleName: "OUTPatient",
            //        SubModuleId: 70,
            //        SubModuleName: "History",
            //        ScreenType: "Copy(Family History)",
            //        ActionType: "Accessed",
            //        OldActionDescription: "",
            //        NewActionDescription:
            //            `Copied Family History values from Appointment Date : ${sourceItem.AppointmentDate}\n` +
            //            `Copied values are:\n` +
            //            copiedLogs.trim(),
            //        ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
            //    };

            //    $scope.AddAuditLogNew(LogItem);
            //}
            if (duplicateFound) {
                alertify.error('Data Is Already Added');
            }     
            //$scope.obj.isNKFHSelected = false;
        };


