            let copiedLogs = [];
            if ($scope.SystemicHistoryArray.length > 0) {
                
                angular.forEach($scope.SystemicHistoryArray , function (Sitem) {
                    if (Sitem.StatusId == 1 || Sitem.HistoryId == 1) {

                        if ($scope.Historyobj.SystemicHistoryArray.length !== 0) {
                            var List = $filter("filter")($scope.Historyobj.SystemicHistoryArray, { "HistoryId": 1 }, true);

                            if (List.length > 0) {
                                angular.forEach(List, function (item) {
                                    if (item.PatientDetailId === 0) {
                                        var indexToRemove = $scope.Historyobj.SystemicHistoryArray.indexOf(item);
                                        if (indexToRemove !== -1) {
                                            $scope.Historyobj.SystemicHistoryArray.splice(indexToRemove, 1);
                                        }
                                    }
                                    else {
                                        item.IsChecked = false;
                                        item.DeleteInd = 'Y';
                                    }
                                });


                            }

                            angular.forEach($scope.obj.SystemicHistoryArray, function (item, index) {
                                item.IsEdit = false;

                            });
                        }

                        let PreviousSystemicHistory  = $filter("filter")($scope.obj.SystemicHistoryArray, { "IsChecked": true }, true)
                        if (Sitem.HistoryId == 1 && PreviousSystemicHistory.length > 0) {
                            return false;
                        }

                        $scope.obj.isNKSHSelected = false;
                        if (Sitem.HistoryId == 1) {
                            $scope.obj.isNKSHSelected = true;
                        }
                        $scope.Historyobj.SystemicHistoryArray.push(Sitem);
                       // copiedLogs.push(formatPastMedicalHistoryCopy(object));
                    }
                });
            }
            if ($scope.Historyobj.SystemicHistoryArray.length > 0) {
                angular.forEach($scope.Historyobj.SystemicHistoryArray, function (Sitem) {
                    Sitem.PatientDetailId = null;
                });
            }
