        $scope.CopyLifeHistory = function (life, Ritem, Nitem) {
            let isDuplicateFound = false;         
            $scope.LifestyleHistory = angular.copy(life);

            if ($scope.LifestyleHistory.length > 0) {
                //let copiedLogs = formatLifestyleCopy(
                //    $scope.LifestyleHistory || []
                   
                //);
                angular.forEach($scope.LifestyleHistory, function (Litem) {
                    var isDuplicate = $scope.obj.LifestyleHistoryArray.some(function (existingItem) {
                        return existingItem.HistoryId === Litem.HistoryId;
                    });

                    if (!isDuplicate) {
                        $scope.obj.LifestyleHistoryDetails = angular.copy($scope.LifestyleHistory);
                        angular.forEach($scope.obj.LifestyleHistoryDetails, function (Sitem) {
                            Sitem.PatientDetailId = null;

                            if (Sitem.HistoryId == 3) {
                                if (Sitem.DrugArray.length > 0) {
                                    angular.forEach(Sitem.DrugArray, function (DAitem) {
                                        DAitem.DrugHistoryId = 0;
                                        DAitem.ActiveInd = "Y";
                                    });
                                }
                                if ($scope.DrugNames.length > 0) {
                                    Sitem.DrugArray = Sitem.DrugArray || [];
                                    if (Sitem.DrugArray.length > 0) {
                                        angular.forEach($scope.DrugNames, function (drugName) {
                                            var matchedDrug = $filter('filter')(Sitem.DrugArray, { HistoryHabitsId: drugName.HistoryHabitsID, ActiveInd: 'Y' }, true);
                                            if (matchedDrug.length > 0) {
                                                drugName.Ischecked = true;
                                            }
                                        });
                                    }
                                }
                            }
                        });
                        $scope.obj.LifestyleHistoryRemarks = Ritem || "";
                        Nitem.IsLifecopied = true;                                         
                    } else {
                      

                        if ($scope.obj.LifestyleHistoryArray.length > 0) {
                            angular.forEach($scope.obj.LifestyleHistoryArray, function (item) {
                                if (item.SmokingType == 'No' &&  item.AlcoholType == 'No' &&  item.DrugType == 'No' && item.PsychisType == 'No') {
                                    if (item.PatientDetailId != 0) {
                                        item.DeleteInd = 'Y';
                                    }
                                    else {
                                        var removeindex = $scope.obj.LifestyleHistoryArray.indexOf(item);
                                        if (removeindex > -1) {
                                            $scope.obj.LifestyleHistoryArray.splice(removeindex, 1);
                                        }
                                    }

                                    if (item.HistoryId == 3) {
                                        var DrugItem = $scope.obj.LifestyleHistoryArray.find(item => item.HistoryId === 3);
                                        if (DrugItem) {
                                            let array = [];
                                            angular.forEach(DrugItem.DrugArray, function (item) {
                                                if (item.DrugHistoryId != 0) {
                                                    item.ActiveInd = 'N';
                                                    array.push(item);
                                                } else {
                                                    var removeindex = DrugItem.DrugArray.indexOf(item);
                                                    if (removeindex > -1) {
                                                        DrugItem.DrugArray.splice(removeindex, 1);
                                                    }
                                                }
                                            });
                                            DrugItem.DrugArray = array || [];                                                                                                                   
                                        }
                                    }

                                    $scope.obj.LifestyleHistoryDetails = angular.copy($scope.LifestyleHistory);
                                    angular.forEach($scope.obj.LifestyleHistoryDetails, function (Sitem) {
                                        Sitem.PatientDetailId = null;
                                    });
                                    $scope.obj.LifestyleHistoryRemarks = Ritem || "";
                                    Nitem.IsLifecopied = true;

                                    $scope.obj.LifestyleHistoryDetails = $scope.obj.LifestyleHistoryDetails.concat($scope.obj.LifestyleHistoryArray);

                                }
                                else {
                                    isDuplicateFound = true;
                                    $scope.obj.LifestyleHistoryDetails = angular.copy($scope.obj.LifestyleHistoryArray);
                                }
                            });                      

                        } 
                       
                                       
                    }
                });

                //if ($scope.obj.LifestyleHistoryRemarks) {
                //    copiedLogs += `\nLifestyle History Notes : ${$scope.obj.LifestyleHistoryRemarks}`;
                //}

                //if (copiedLogs.length > 0) {
                //    Nitem.AppointmentDate = $filter('date')(Nitem.AppointmentDate, "MM-dd-yyyy");
                //    let LogItem = {
                //        LogId: 0,
                //        ModuleId: 1,
                //        ModuleName: "OUTPatient",
                //        SubModuleId: 70,
                //        SubModuleName: "History",
                //        ScreenType: "Copy(Lifestyle History)",
                //        ActionType: "Accessed",
                //        OldActionDescription: "",
                //        NewActionDescription:
                //            `Copied Lifestyle History values from Appointment Date : ${Nitem.AppointmentDate}\n` +
                //            `Copied values are:\n` +
                //            copiedLogs.trim(),
                //        ActionDateTime: $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                //    };

                //    $scope.AddAuditLogNew(LogItem);
                //}
                if (isDuplicateFound) {
                    alertify.error('Data Is Already Added');
                }
            }
        };

       
    
