        $scope.CopyPREVIOUSTono = function (ptitem) {

            if ($scope.PatientGraphData.length > 0) {
                angular.forEach($scope.PatientGraphData, function (item) {
                    if (item.Tonometry.length > 0) {
                        item.Tonometry[item.Tonometry.length - 1].iscopied = false;
                    }
                });
            }
            $scope.TonometryObj = GetTonometryObj();
            $scope.TonometryObj.BeforeDilationRightEye = ptitem.BeforeDilationRightEye || "";
            $scope.TonometryObj.BeforeDilationLeftEye = ptitem.BeforeDilationLeftEye || "";
            $scope.TonometryObj.AfterDilationRightEye = ptitem.AfterDilationRightEye || "";
            $scope.TonometryObj.AfterDilationLeftEye = ptitem.AfterDilationLeftEye || "";
            $scope.VisionObj.TonoMetryTypeId = ptitem.InvestigationId || "";
            $scope.VisionObj.InvestigationDesc = ptitem.InvestigationDesc || "";
            $scope.TonometryObj.InvestigationId = ptitem.InvestigationId;
            $scope.TonometryObj.InvestigationDesc = ptitem.InvestigationDesc;
            $scope.TonometryObj.DilationType = ptitem.DilationType || "Before Dilation";

         
            ptitem.iscopied = true;
        }
