        function padArray(arr, length) {
            const filled = Array.isArray(arr) ? [...arr] : [];
            while (filled.length < length) {
                let obj = {
                    data: 'No data' + filled.length, IsNoData: true
                }
                filled.push(obj);
            }
            return filled;
        }

