        /* ---------------- STATE ---------------- */

        $scope.visits = []; // displayed visits
        $scope.visitIndex = 0; // pointer to next visit
        $scope.isLoading = false; // prevent duplicate calls
        $scope.noMoreData = false; // stop when all visits loaded

        /* ---------------- INITIAL LOAD ---------------- */

        $scope.initVisitSummary = function () {

            // reset everything when tab opens
            $scope.visits = [];
            $scope.visitIndex = 0;
            $scope.noMoreData = false;

            // load latest visit first
            $scope.loadOlderVisit();

        };

        /* ---------------- LOAD ONE OLDER VISIT ---------------- */

        $scope.loadOlderVisit = function () {

            // Requirement: only one call
            if ($scope.isLoading || $scope.noMoreData) return;

            $scope.isLoading = true;

            setTimeout(function () {

                // if no more visits
                if ($scope.visitIndex >= $scope.allVisits.length) {
                    $scope.noMoreData = true;
                    $scope.isLoading = false;
                    $scope.$applyAsync();
                    return;
                }

                // pick next visit
                var nextVisit = $scope.allVisits[$scope.visitIndex];

                // avoid duplicate visits
                var exists = $scope.visits.some(function (v) {
                    return v.id === nextVisit.id;
                });

                if (!exists) {
                    $scope.visits.push(nextVisit);
                }

                // move pointer
                $scope.visitIndex++;

                $scope.isLoading = false;
                $scope.$applyAsync();

            }, 500);

        };


