        $scope.GetAllPatientsvisitsscroll = function () {
            var CurrentDate = $filter('date')(new Date(), "yyyy-MM-dd");
            var obj = {
                "PatientId": $scope.Patientid,
                "OrganizationId": $scope.HospitalId,
                "UpcomingVisitsIndicator": false,
                "CurrentDate": CurrentDate,
                "AllBranchInd": "Y",
                "AppointmentStatusIds": "1,2,3,4",
            }
            eHnotePatientVisitReasonServices.GetPatientAppointmentVisitsById(obj).then(function (resp) {
                if (resp.data.Status === "Success") {
                    if (resp.data.rows.length > 0) {
                        $scope.IsMultipleVisits = false;
                        $scope.AllAppointments = [];
                        $scope.AllAppointmentsnew = [];
                        if (resp.data.rows.length > 0) {
                            var TempArray = $filter("filter")(resp.data.rows, function (item) {
                                return (item.AppointmentStatusId == 1 || item.AppointmentStatusId == 2 || item.AppointmentStatusId == 3 || item.AppointmentStatusId == 4) && item.AppointmentDate <= CurrentDate;
                            });
                            if (TempArray.length > 0) {
                                $scope.AllAppointments = angular.copy(TempArray);
                                $scope.AllAppointmentsnew = angular.copy(TempArray);
                            }

                            //$timeout(function () {

                            //    if ($scope.AllAppointmentsnew &&
                            //        $scope.AllAppointmentsnew.length > 0) {

                            //        $scope.ChangesConsultationNew($scope.AllAppointmentsnew[0]);

                            //    }

                            //}, 100);
                            // latest first

                            if ($scope.AllAppointmentsnew && $scope.AllAppointmentsnew.length > 0) {
                                angular.forEach($scope.AllAppointmentsnew, function (x) {
                                    x.IsActive = false;
                                });
                                $scope.AllAppointmentsnew[0].IsActive = true;
                            }
                            $scope.VisitQueue = [];

                            angular.forEach($scope.AllAppointments, function (appt) {

                                if (appt.VisitsArray && appt.VisitsArray.length > 0) {

                                    angular.forEach(appt.VisitsArray, function (visit) {

                                        $scope.VisitQueue.push({
                                            VisitId: visit.VisitId,
                                            AppointmentId: visit.AppointmentId,
                                            AppointmentDate: appt.AppointmentDate,
                                            AppointmentVisitReasonName: appt.AppointmentVisitReasonName,
                                            AppointmentTypeId: appt.AppointmentTypeId,
                                            SurgeryList: appt.SurgeryList || [],
                                            Header: appt,
                                            OrganizationId: visit.OrganizationId,
                                            PatientId: visit.PatientId
                                        });

                                    });
                                }
                            });

                            // reset scroll engine
                            $scope.VisitPointer = 0;
                            $scope.LoadedVisitIds = {};
                            $scope.RenderedVisits = [];
                            $scope.ScrollNoMoreData = false;
                            $scope.EnabledVisitIds = {};
                            $scope.EnabledAppointmentIds = {};
                            // load first visit (default latest)
                            $scope.loadNextVisit();

                            console.log($scope.AllAppointments);
                        }
                    }
                };
            }, function (err) {
                alertify.error("Getting Failed");
            });
        }
